describe('Responsive Data Table', () => {
    beforeEach(() => {
        cy.visit('/data-table'); // Adjust the URL to the actual page
        cy.viewport('iphone-6'); // Simulate a small screen
    });

    it('should display data tables stacked vertically on small screens', () => {
        cy.get('.data-table').should('have.length.greaterThan', 1); // Ensure there are multiple tables
        cy.get('.data-table').each(($table) => {
            cy.wrap($table).should('be.visible'); // Check each table is visible
            cy.wrap($table).should('have.css', 'display', 'block'); // Ensure tables are displayed as block
        });
    });

    it('should not display tables side by side on small screens', () => {
        cy.get('.data-table').then(($tables) => {
            const tablePositions = [];
            $tables.each((index, table) => {
                const position = Cypress.$(table).position().top;
                tablePositions.push(position);
            });
            const allStacked = tablePositions.every((pos, index) => index === 0 || pos > tablePositions[index - 1]);
            expect(allStacked).to.be.true; // Ensure all tables are stacked vertically
        });
    });
});
